{
  "summary": "Long‑acting GLP‑1 receptor agonists (including both injectable and oral forms) reduce the incidence of major adverse cardiovascular events (MACE) by about 14% in adults with type 2 diabetes, based on a meta‑analysis of 10 RCTs (n=71,351) (PMID 40156846). Oral semaglutide 14 mg daily significantly lowers the risk of MACE (HR 0.86, 95% CI 0.77‑0.96) compared with placebo in patients with type 2 diabetes and high cardiovascular risk, atherosclerotic disease, or chronic kidney disease (PMID 40162642). SGLT2 inhibitors consistently reduce the risk of chronic kidney disease progression across eGFR subgroups and are associated with a modest reduction in cardiovascular events (HR 0.62 for CKD progression) (PMID 41203232).",
  "claims": [
    {
      "statement": "Long‑acting GLP‑1 receptor agonists (including both injectable and oral forms) reduce the incidence of major adverse cardiovascular events (MACE) by about 14% in adults with type 2 diabetes, based on a meta‑analysis of 10 RCTs (n=71,351).",
      "pmids": ["40156846"],
      "confidence": "moderate"
    },
    {
      "statement": "Oral semaglutide 14 mg daily significantly lowers the risk of MACE (HR 0.86, 95% CI 0.77‑0.96) compared with placebo in patients with type 2 diabetes and high cardiovascular risk, atherosclerotic disease, or chronic kidney disease.",
      "pmids": ["40162642"],
      "confidence": "moderate"
    },
    {
      "statement": "SGLT2 inhibitors consistently reduce the risk of chronic kidney disease progression across eGFR subgroups and are associated with a modest reduction in cardiovascular events (HR 0.62 for CKD progression).",
      "pmids": ["41203232"],
      "confidence": "moderate"
    }
  ],
  "limitations": [
    "Evidence is derived from meta‑analyses and RCTs; indirect comparisons between drug classes are limited.",
    "Age‑ and sex‑specific effects remain uncertain (PMID 39899304).",
    "Long‑term outcomes beyond 2‑3 years are not fully addressed."
  ]

  ,
  "overall_grade": "moderate"
}
